mutations.content:
on left click with firework rocket:
    if name of player's tool is "&bTeleport Elytra":
        set {_loc} to location of player
        set {_y} to y-coordinate of {_loc}
        set {_found} to false
        loop integers from 1 to 20:
            set {_check} to location(x-coordinate of {_loc}, {_y} - loop-value, z-coordinate of {_loc}, world of player)
            if block at {_check} is not air:
                set {_target} to location(x-coordinate of {_loc}, {_y} - loop-value + 1, z-coordinate of {_loc}, world of player)
                teleport player to {_target}
                play sound "entity.enderman.teleport" with volume 1 and pitch 1 at player
                set {_found} to true
                stop loop
        if {_found} is false:
            send "&cNo ground found below you!" to player
